class FMCreateReservationAction extends FMReservationPage
{
    private utcdatetime startDateInternal;
    private utcdatetime endDateInternal;
    private int64 customerRecIdInternal;
    private int64 vehicleRecIdInternal;
    NoYesError NoYesErrorInternal;
    private FMRentalChargeType rentalChargeTypeInternal;

}

Method.Source:
[
    SysAppLookupField(tableStr(FMCustomer)),
    SysAppField(fieldStr(FMRental, Customer), "Select customer")
]
public int64 customerRecId(int64 _value = customerRecIdInternal)
{
    customerRecIdInternal = _value;
    return customerRecIdInternal;
}

[
    SysAppLookupField(tableStr(FMVehicle)),
    SysAppField(fieldStr(FMRental, Vehicle), "Select vehicle")
]
public int64 vehicleRecId(int64 _value = vehicleRecIdInternal)
{
    vehicleRecIdInternal = _value;
    return vehicleRecIdInternal;
}

[SysAppField(fieldStr(FMRentalCharge, ChargeType ), "Charge type")]
public FMRentalChargeType rentalChargeType(FMRentalChargeType _value=rentalChargeTypeInternal)
{
    rentalChargeTypeInternal = _value;
    return rentalChargeTypeInternal;
}

[SysAppField(fieldStr(FMRental, StartDate), "Pickup")]
public utcdatetime startDate(utcdatetime _value=startDateInternal)
{
    startDateInternal = _value;
    return startDateInternal;
}

[SysAppField(fieldStr(FMRental, EndDate), "Return")]
public utcdatetime endDate(utcdatetime _value=endDateInternal)
{
    endDateInternal = _value;
    return endDateInternal;
}

public boolean validate(SysAppResponse _response)
{
    boolean validationPassed = true;

    if (!customerRecIdInternal)
    {
        _response.addMessage(new SysAppResponseMessage("Customer should be selected", SysAppMessageType::Error));
        validationPassed = false;
    }

    if (!customerRecIdInternal)
    {
        _response.addMessage(new SysAppResponseMessage("Vehicle should be selected", SysAppMessageType::Error));
        validationPassed = false;
    }

    return validationPassed;
}

public SysAppResponse createReservation(SysAppEntityContext _entityContext, List _filterContextList)
{
    SysAppResponse response = new SysAppResponse();

    if (this.validate(response))
    {
        FMRental rentalTable;

        rentalTable.Customer = customerRecIdInternal;
        rentalTable.Vehicle = vehicleRecIdInternal;
        rentalTable.StartDate = startDateInternal;
        rentalTable.EndDate = endDateInternal;

        ttsbegin;
        rentalTable.insert();
        ttscommit;

        response.addCommit(SysAppEntityContext::constructFromBuffer(rentalTable));
    }

    return response;
}
